contracts.source:
export interface WorkbenchWindow {
  /** 壳身份（nanoid） */
  id: string;
  typeId: string;
  /** 业务身份，如 'note_xxx' / 'sess_xxx'；single 应用为 null */
  instanceKey: string | null;
  title: string;
  /** floating 时的位置尺寸；tiled/maximized 时为落位前快照的冗余（渲染以 computeTiledFrame 为准） */
  frame: Frame;
  /** 进入 tiled/maximized 前的原始 frame（macOS 恢复语义） */
  restoreFrame: Frame | null;
  displayMode: DisplayMode;
  minimized: boolean;
  zIndex: number;
  createdAt: number;
  lastFocusedAt: number;
}

export interface ActivationContext {
  windowId: string;
  instanceKey: string | null;
  action: string;
  payload?: unknown;
}

export interface AppDefinition {
  typeId: string;
  /** i18n key（namespace: workbench） */
  nameKey: string;
  icon: React.ReactNode;
  /** false when the window requires resource context and cannot be launched on its own. */
  showInLauncher?: boolean;
  instanceMode: 'single' | 'multi';
  /** 调度器内存预算权重：PDF/教材=3，编辑器/Chat/思维导图=2，纯展示=1 */
  memoryWeight: 1 | 2 | 3;
  /**
   * Keep the app mounted and visually present while another internal window
   * covers it. Native child surfaces need this so the platform clip host can
   * yield only the covered pixels instead of hiding the entire surface.
   */
  keepAliveWhenOccluded?: boolean;
  defaultFrame: Size;
  minSize: Size;
  render: React.LazyExoticComponent<React.FC<AppWindowProps>>;
  /**
   * 应用的数据由哪个 Host 插件提供（如 `'dstu.anki'`）。经 `contributeWorkbenchApp` 登记时由 `dstu.ui.workbench`
   * 按 Host 状态处理：缺失时不出现在工作台；降级时窗口内显示 Host 不可用面板（已打开的窗口即时切换）；
   * 恢复后照常。Host 清单未到或没有 UI 内核时按在线处理。
   */
  hostPlugin?: string;
  /** 一次性指令送达（scrollToMessage / gotoPage 等）；可返回结构化回执 */
  onActivation?: (
    ctx: ActivationContext,
  ) => ActivationHandlerResult | Promise<ActivationHandlerResult>;
  /** Optional, self-describing semantic control surface for ACR 2.0. */
  agentManifest?: AppAgentManifest;
  /** Dock 角标数据源（拉模式，Dock 轮询/订阅由 Dock 实现决定） */
  badgeSource?: () => AppBadge | null;
  /** 关闭拦截（未保存提示）；返回 false 阻止关闭。缺省 = 直接关 */
  canClose?: (instanceKey: string | null) => boolean | Promise<boolean>;
  /**
   * suspend 契约（2026-08 Wave2 扩展，新增可选字段）：
   * 调度器把 background 窗降为 frozen（卸载 React 子树）前询问本回调；
   * 返回 false = 本窗当前不可冻（典型：有未保存编辑，冻结会丢内存态）。
   *
   * 约定：调度器热路径【不 await】——dirty 类查询必须同步返回 boolean
   * （isContentDirty / isWindowDirty 均为同步）；返回 Promise 时热路径
   * 视为「可冻」，异步结果仅供非热路径调用方参考。缺省 = 总是可冻。
   */
  canSuspend?: (instanceKey: string | null) => boolean | Promise<boolean>;
  /**
   * 可选的冻结前保存挂点：返回 true 表示已保存、随后可安全冻结。
   * 仅供非热路径在「窗口脏但有保存能力、且调用方明确要冻」时使用；
   * 调度器本身绝不自动调用（默认策略：脏窗保持 background，永不 frozen）。
   */
  prepareSuspend?: (instanceKey: string | null) => boolean | Promise<boolean>;
  /**
   * Ctrl+W is normally owned by the workbench window manager. Tabbed apps can
   * opt in to receive it themselves, for example to close their active tab.
   */
  handlesCloseShortcut?: boolean;
  /**
   * Ctrl+Tab / Ctrl+Shift+Tab 让位协议（分层实现见 useWorkbenchShortcuts）：
   * 默认归工作台窗口切换器；带内部标签页的应用（编辑器 / 浏览器等）声明
   * 本标志后接管这组按键做内部标签循环。
   *
   * 分层规则（自上而下短路）：
   * 1. 焦点在可编辑目标 / IME 组合中 → 壳层输入守卫本就不响应，谁也不抢；
   * 2. 切换器会话已开启（按住 Ctrl 循环中）→ 壳层保持所有权直至松开 Ctrl，
   *    壳层会 preventDefault —— 应用侧监听器必须跳过 defaultPrevented 事件；
   * 3. 会话未开启且焦点应用声明本标志 → 壳层让位（不 preventDefault、
   *    不开切换器），应用自持的 keydown 监听器消费并 preventDefault。
   *
   * 声明后该应用聚焦期间不可再用 Ctrl+Tab 呼出窗口切换器；窗口切换仍有
   * Dock / 俯瞰（Ctrl+Alt+E）/ 同应用循环（Ctrl+`）等入口。
   */
  handlesTabCycleShortcut?: boolean;
}

export interface LaunchRequest {
  typeId: string;
  instanceKey?: string;
  /** 瞬态，不进快照 */
  payload?: unknown;
  /** 桌面坐标系落点；仅新建窗口生效，窗口以该点为中心并钳制进桌面。 */
  dropPoint?: { x: number; y: number };
  /**
   * 落位策略（仅新建窗口生效；窗口已存在时只聚焦，绝不移动）。
   * 'beside'：开在来源窗旁边，不遮住来源窗（对话里点页码开阅读器等），见 core/besidePlacement。
   */
  placement?: LaunchPlacement;
  reason: LaunchReason;
}

export interface LaunchPlacement {
  mode: 'beside';
  /** 来源窗 id；缺省取当前焦点窗 */
  anchorWindowId?: string | null;
}

export interface ActivateRequest {
  typeId: string;
  instanceKey: string;
  action: string;
  payload?: unknown;
  /** 目标窗口不存在时的兜底 launch */
  fallbackLaunch?: LaunchRequest;
}

export interface WorkbenchSnapshotV1 {
  version: 1;
  windows: WorkbenchWindow[];
  dockPinned: string[];
  /** key: `${leftWindowId}:${rightWindowId}`，value: 左侧占比 0–1 */
  tilingRatios: Record<string, number>;
  /**
   * 壁纸配置；imageBlur/imageDim/imageVignette 为图片壁纸的可选适配字段
   * （新增可选扩展，向后兼容），语义与 WallpaperLayer 的 WallpaperConfig 一致。
   */
  wallpaper?: {
    kind: 'theme' | 'image';
    value: string;
    /** 高斯模糊半径 px，sanitize 钳制 0–40 */
    imageBlur?: number;
    /** 额外压暗，sanitize 钳制 0–0.6 */
    imageDim?: number;
    /** 边缘暗角开关 */
    imageVignette?: boolean;
  };
  materialTier?: MaterialTier;
  /**
   * O11 追加（可选）：快照保存时的桌面尺寸。
   * 恢复时若与当前桌面不一致，hydrate 按比例缩放窗口位置并钳回可视区
   * （多显示器 / 分辨率变化自适应）。旧快照无此字段 → 仅做钳制兜底。
   */
  desktopSize?: Size;
}
